class PrintConfig {
  int? dstWidth;
  int? dstHeight;
  int? horizontalStartPosition;
  int? verticalStartPosition;
  int? width;
  int? level;
  String? base64Image;

  PrintConfig(
      { this.dstWidth= 110,
        this.dstHeight=140,
        this.horizontalStartPosition=60,
        this.verticalStartPosition=60,
        this.width=110,
        this.level=140,
        this.base64Image=""});


  Map<String, dynamic> toJson() {
    final Map<String, dynamic> data = new Map<String, dynamic>();
    data['dstWidth'] = dstWidth;
    data['dstHeight'] = dstHeight;
    data['horizontalStartPosition'] = horizontalStartPosition;
    data['verticalStartPosition'] = verticalStartPosition;
    data['width'] = width;
    data['level'] = level;
    data['base64Image'] = base64Image;
    return data;
  }
}
